<script>const customer=document.getElementById('customer_party_id'),body=document.getElementById('advance-sources');const esc=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML};async function loadSources(){body.replaceChildren();if(!customer.value)return;const r=await fetch('{{ route('accounting.customer-advance-returns.sources') }}?party_id='+encodeURIComponent(customer.value));const j=await r.json();for(const s of j.sources||[]){const i=body.children.length,tr=document.createElement('tr');tr.dataset.available=Number(s.available_amount||0);tr.innerHTML='<td>'+esc(s.source_number)+'</td><td>'+esc(s.advance_source_type)+'</td><td>'+esc(s.source_date)+'</td><td>'+esc(s.booking_id||'')+'</td><td>'+Number(s.original_amount||0).toFixed(2)+'</td><td>'+Number(s.adjusted_amount||0).toFixed(2)+'</td><td>'+Number(s.returned_amount||0).toFixed(2)+'</td><td>'+Number(s.available_amount||0).toFixed(2)+'</td><td><input type="checkbox" data-select><input type="number" step="0.01" min="0.01" max="'+Number(s.available_amount||0)+'" disabled data-amount name="allocations['+i+'][amount]"><input type="hidden" disabled data-source name="allocations['+i+'][advance_source_type]" value="'+esc(s.advance_source_type)+'"><input type="hidden" disabled data-source name="allocations['+i+'][advance_source_id]" value="'+Number(s.advance_source_id)+'"></td>';body.append(tr)}updateTotals()}function updateTotals(){let available=0,selected=0;body.querySelectorAll('tr').forEach(tr=>{available+=Number(tr.dataset.available||0)});body.querySelectorAll('[data-amount]').forEach(i=>selected+=Number(i.value||0));document.getElementById('available-total').textContent=available.toFixed(2);document.getElementById('selected-total').textContent=selected.toFixed(2);document.getElementById('remaining-total').textContent=(available-selected).toFixed(2);document.getElementById('return-amount').value=selected.toFixed(2)}customer.addEventListener('change',loadSources);body.addEventListener('change',e=>{if(e.target.matches('[data-select]')){e.target.closest('tr').querySelectorAll('[data-source],[data-amount]').forEach(x=>x.disabled=!e.target.checked);updateTotals()}});body.addEventListener('input',updateTotals);document.querySelector('[name=payment_proof]')?.addEventListener('change',e=>document.querySelector('[data-proof-label]').textContent=e.target.files?.[0]?.name||'No file selected');loadSources();</script>
